import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

import type { BundleGroup, BundleKind } from '../app/blocks/_shared/types';
import type { RegistryItemDefinition } from '../registry/items';
import type { BlockManifest } from '../registry/ndeko/blocks/types';
import {
  componentPartsOf,
  identifierOf,
  mergedDependencies,
  sortedAlphabetically,
  titleOf,
} from './registry-catalog';

const ROOT = path.join(__dirname, '..');
const GENERATED_NOTICE =
  '// Generated by scripts/build-registry.ts from the block and template manifests. Do not edit.';

function rootOf(kind: BundleKind) {
  return path.join(ROOT, 'registry/ndeko', kind);
}

function generatedDirOf(kind: BundleKind) {
  return path.join(ROOT, 'app', kind, '_generated');
}

function groupSlugs(kind: BundleKind) {
  const root = rootOf(kind);
  if (!fs.existsSync(root)) {
    return [];
  }
  const entries = fs.readdirSync(root, { withFileTypes: true });
  const folders = entries.filter((entry) => entry.isDirectory());
  const names = folders.map((folder) => folder.name);
  return sortedAlphabetically(names);
}

async function groupOf(kind: BundleKind, slug: string) {
  const manifestPath = path.join(rootOf(kind), slug, '_manifest.ts');
  if (!fs.existsSync(manifestPath)) {
    return null;
  }
  const loaded = await import(pathToFileURL(manifestPath).href);
  const manifest: BlockManifest = loaded.manifest;
  const entries = manifest.map((entry) => ({ ...entry, group: slug }));
  const group: BundleGroup = { slug, name: titleOf(slug), entries };
  return group;
}

function isGroup(value: BundleGroup | null): value is BundleGroup {
  return value !== null;
}

export async function collectBundles(kind: BundleKind) {
  const slugs = groupSlugs(kind);
  const loaded = await Promise.all(slugs.map((slug) => groupOf(kind, slug)));
  return loaded.filter(isGroup);
}

export function bundleItemsOf(
  kind: BundleKind,
  groups: BundleGroup[]
): RegistryItemDefinition[] {
  return groups.flatMap((group) =>
    group.entries.map((entry) => {
      const folder = `registry/ndeko/${kind}/${group.slug}/${entry.name}`;
      const files = entry.files.map((file) => ({
        path: `${folder}/${file}`,
        type: 'registry:component' as const,
        target: `components/${kind}/${entry.name}/${file}`,
      }));
      const absolutePaths = files.map((file) => path.join(ROOT, file.path));
      const componentParts = componentPartsOf(absolutePaths);
      const { registryDependencies, dependencies } = mergedDependencies([
        ...absolutePaths,
        ...componentParts.paths,
      ]);
      return {
        name: entry.name,
        type: 'registry:block',
        title: entry.title,
        description: entry.description,
        files: [...files, ...componentParts.files],
        dependencies,
        registryDependencies,
        categories: [kind, group.slug],
      };
    })
  );
}

function entryModuleOf(fileName: string) {
  return fileName.replace(/\.tsx?$/, '');
}

function previewModuleOf(kind: BundleKind, group: BundleGroup) {
  const imports = group.entries.map((entry) => {
    const entryFile = entryModuleOf(entry.files[0]);
    return `import ${identifierOf(entry.name)} from '@/registry/ndeko/${kind}/${group.slug}/${entry.name}/${entryFile}';`;
  });
  const rows = group.entries.map(
    (entry) => `  '${entry.name}': ${identifierOf(entry.name)},`
  );
  return [
    GENERATED_NOTICE,
    "import type { ComponentType } from 'react';",
    '',
    ...imports,
    '',
    'export const previews: Record<string, ComponentType> = {',
    ...rows,
    '};',
    '',
  ].join('\n');
}

function indexModuleOf(groups: BundleGroup[]) {
  const data = JSON.stringify(groups, null, 2);
  return [
    GENERATED_NOTICE,
    "import type { BundleGroup } from '@/app/blocks/_shared/types';",
    '',
    `export const groups: BundleGroup[] = ${data};`,
    '',
  ].join('\n');
}

/*
 * Apart from the data, and on the client: next/dynamic splits every group into its own chunk, so a
 * page ships only the group it renders. Imported from the server, the same imports would put every
 * group in every page that reaches them.
 */
function previewHostsModuleOf(groups: BundleGroup[]) {
  const hosts = groups.map(
    (group) =>
      `  '${group.slug}': dynamic(() => import('./${group.slug}').then(previewHostOf)),`
  );
  return [
    GENERATED_NOTICE,
    "'use client';",
    '',
    "import dynamic from 'next/dynamic';",
    "import type { ComponentType } from 'react';",
    '',
    'import {',
    '  previewHostOf,',
    '  type PreviewHostProps,',
    "} from '@/app/_site/preview-host';",
    '',
    'export const previewHosts: Record<string, ComponentType<PreviewHostProps>> = {',
    ...hosts,
    '};',
    '',
  ].join('\n');
}

export function writeBundleModules(kind: BundleKind, groups: BundleGroup[]) {
  const generatedDir = generatedDirOf(kind);
  fs.mkdirSync(generatedDir, { recursive: true });
  for (const group of groups) {
    const target = path.join(generatedDir, `${group.slug}.ts`);
    fs.writeFileSync(target, previewModuleOf(kind, group));
  }
  const indexTarget = path.join(generatedDir, 'index.ts');
  fs.writeFileSync(indexTarget, indexModuleOf(groups));
  const hostsTarget = path.join(generatedDir, 'preview-hosts.tsx');
  fs.writeFileSync(hostsTarget, previewHostsModuleOf(groups));
}
